<?php
require_once __DIR__ . '/config/bootstrap.php';
require_once __DIR__ . '/data/repository.php';
$user = require_role(['Administrador', 'Repositor']);
$pdo = db();
$editing = null; $error = null;
if (isset($_GET['edit']) && is_string($_GET['edit']) && ctype_digit($_GET['edit'])) $editing = product($pdo, (int) $_GET['edit']);
$search = isset($_GET['q']) && is_string($_GET['q']) ? trim($_GET['q']) : ''; $products = products($pdo, $search); $categories = categories($pdo); $lowStock = low_stock($pdo);
$pageTitle = 'Inventario'; $activePage = 'inventario';
require __DIR__ . '/includes/header.php';
?>
<section class="page-heading"><div><p class="eyebrow">Catálogo y existencias</p><h1>Inventario</h1><p class="muted">Administra tus productos y mantén el stock bajo control.</p></div><button class="btn btn-primary" type="button" data-scroll-to="inventarioForm">+ Nuevo producto</button></section>
<div class="content-grid inventory-layout"><section class="panel form-panel"><div class="panel-heading"><div><p class="eyebrow">Nuevo registro</p><h2>Alta de producto</h2></div></div><form id="inventarioForm" class="form-grid" method="post" data-product-form><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($editing['id'] ?? '') ?>"><div class="form-row"><label for="name">Nombre<input id="name" name="name" type="text" value="<?= e($editing['name'] ?? '') ?>" placeholder="Ej. Café Premium" maxlength="150" required></label><label for="category_id">Categoría<select id="category_id" name="category_id" required><option value="">Selecciona</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= (int) ($editing['category_id'] ?? 0) === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label></div><div class="form-row"><label for="cost">Precio costo<input id="cost" name="cost" type="number" min="0" max="9999999999.99" step="0.01" value="<?= e($editing['cost'] ?? '') ?>" required></label><label for="price">Precio venta<input id="price" name="price" type="number" min="0.01" max="9999999999.99" step="0.01" value="<?= e($editing['price'] ?? '') ?>" required></label></div><div class="form-row"><label for="unit">Unidad de medida<input id="unit" name="unit" type="text" value="<?= e($editing['unit'] ?? 'unidad') ?>" maxlength="30" required></label><label for="stock">Stock actual<input id="stock" name="stock" type="number" min="0" max="999999999" step="1" value="<?= e($editing['stock'] ?? '') ?>" required></label></div><label for="minimum_stock">Stock mínimo<input id="minimum_stock" name="minimum_stock" type="number" min="0" max="999999999" step="1" value="<?= e($editing['minimum_stock'] ?? '') ?>" required></label><?php if ($error): ?><p class="error-message"><?= e($error) ?></p><?php endif; ?><button class="btn btn-primary" type="submit">Guardar producto <span>→</span></button></form></section><section class="panel alert-panel inventory-alert"><div><p class="eyebrow">Atención</p><h2>Alertas de stock</h2></div><ul id="alertList" class="alert-list"><?php foreach ($lowStock as $item): ?><li><span class="status-dot critical"></span><span><strong><?= e($item['name']) ?></strong><small><?= quantity($item['stock']) ?> unidades · mínimo <?= quantity($item['minimum_stock']) ?></small></span><b>Revisar</b></li><?php endforeach; ?><?php if (!$lowStock): ?><li class="empty-state">No hay alertas activas.</li><?php endif; ?></ul></section></div>
<section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">Vista general</p><h2>Listado de productos <span id="productCount" class="count-badge"><?= count($products) ?></span></h2></div><form class="table-tools" method="get"><input type="search" name="q" value="<?= e($search) ?>" placeholder="Buscar producto..." aria-label="Buscar producto"></form></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio venta</th><th>Stock</th><th>Mínimo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="productosBody"><?php foreach ($products as $product): ?><tr data-product-id="<?= e($product['id']) ?>"><td><strong><?= e($product['name']) ?></strong><small><?= e($product['unit']) ?></small></td><td><?= e($product['category_name']) ?></td><td><?= money($product['price']) ?></td><td><?= quantity($product['stock']) ?></td><td><?= quantity($product['minimum_stock']) ?></td><td><span class="status-pill <?= $product['stock'] <= $product['minimum_stock'] ? 'status-low' : 'status-ok' ?>"><?= $product['stock'] <= $product['minimum_stock'] ? 'Stock bajo' : 'En stock' ?></span></td><td><button class="table-action" type="button" data-edit-product="<?= e($product['id']) ?>">Editar</button><button class="table-action danger" type="button" data-delete-product="<?= e($product['id']) ?>" data-confirm="¿Retirar este producto?">Retirar</button></td></tr><?php endforeach; ?><?php if (!$products): ?><tr data-empty-row><td colspan="7" class="empty-state">No hay productos que coincidan con la búsqueda.</td></tr><?php endif; ?></tbody></table></div></section>
